import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

import {
  CUSTOM_END_MARKER,
  CUSTOM_START_MARKER,
  classifyTouchedSkills,
  stripCustomBlock,
  touchedSkillIds,
} from "../../scripts/skills/lib/skillsSyncScope.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const SCRIPT = path.join(root, "scripts/skills/generate-agent-skills.mjs");

const GENERATED =
  "---\nname: x\n---\n\n<!-- generated by src/lib/agentSkills/generator.ts -->\n\n## Body\n";
const withCustom = (custom: string, body = GENERATED) =>
  `${body}\n${CUSTOM_START_MARKER}\n${custom}\n${CUSTOM_END_MARKER}\n`;

test("the custom-block markers match the generator's", async () => {
  const fs = await import("node:fs");
  const generator = fs.readFileSync(path.join(root, "src/lib/agentSkills/generator.ts"), "utf8");
  assert.ok(generator.includes(`const CUSTOM_START_MARKER = "${CUSTOM_START_MARKER}";`));
  assert.ok(generator.includes(`const CUSTOM_END_MARKER = "${CUSTOM_END_MARKER}";`));
});

test("stripCustomBlock drops only the hand-written block", () => {
  assert.equal(stripCustomBlock(GENERATED), GENERATED);
  assert.equal(stripCustomBlock(withCustom("hello")), `${GENERATED}\n\n`);
  assert.equal(stripCustomBlock(withCustom("a")), stripCustomBlock(withCustom("b")));
  assert.notEqual(
    stripCustomBlock(withCustom("a")),
    stripCustomBlock(withCustom("a", GENERATED + "more\n"))
  );
});

test("touchedSkillIds: only files inside a skill directory count", () => {
  assert.deepEqual(
    touchedSkillIds([
      "skills/README.md",
      "skills/omni-mcp/SKILL.md",
      "skills/omni-inference/references/endpoints.md",
      "skills/omni-mcp/references/endpoints.md",
      "docs/openapi.yaml",
    ]),
    ["omni-inference", "omni-mcp"]
  );
});

test("classify: generated text or a references/ file edited → strict; custom block only → not", () => {
  const base: Record<string, string> = {
    "skills/a/SKILL.md": withCustom("old"),
    "skills/b/SKILL.md": withCustom("same"),
    "skills/c/SKILL.md": GENERATED,
  };
  const head: Record<string, string> = {
    "skills/a/SKILL.md": withCustom("new words"), // custom block only
    "skills/b/SKILL.md": withCustom("same", GENERATED + "hand edit\n"), // generated text edited
    "skills/c/SKILL.md": GENERATED,
    "skills/d/SKILL.md": GENERATED, // new skill file
  };
  const result = classifyTouchedSkills({
    changedFiles: [
      "skills/a/SKILL.md",
      "skills/b/SKILL.md",
      "skills/c/references/endpoints.md",
      "skills/d/SKILL.md",
    ],
    readBase: (p) => base[p] ?? null,
    readHead: (p) => head[p] ?? null,
  });
  assert.deepEqual(result, { strict: ["b", "c", "d"], customOnly: ["a"] });
});

function runScript(args: string[], env: Record<string, string>) {
  const res = spawnSync(process.execPath, ["--import", "tsx/esm", SCRIPT, ...args], {
    cwd: root,
    encoding: "utf8",
    env: { PATH: process.env.PATH ?? "", HOME: process.env.HOME ?? "", ...env },
    timeout: 120_000,
  });
  return { code: res.status, out: `${res.stdout}${res.stderr}` };
}

test("pr mode with no skill edited skips with the shared SKIP line (exit 0)", () => {
  const head = spawnSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" });
  const r = runScript(["--mode=pr"], { BASE_SHA: head.stdout.trim(), CI: "true" });
  assert.equal(r.code, 0, r.out);
  assert.match(r.out, /\[agent-skills-sync\] SKIP reason=pr-mode — /);
  assert.match(r.out, /mode=pr \(flag: --mode=pr\)/);
  assert.match(r.out, /the strict check runs in release mode/);
});
